int fib(int n){
    if (n <= 1) return n;
    int f0 = 0， f1 = 1， cur = 0；
    for (int i= 2；i <= n; i+) {
        cur = f0 + f1;
        f0 = f1;
        f1 = cur;
    }
    return cur;
}

